'use strict';
let pyqQuestions=[],pyqRequest=null,pyqSubject='all',pyqQuery='',pyqMode='all',pyqPage=0,pyqRouteToken=0,pyqSolutionOpen=false;
let pyqProgress={};
try{const x=JSON.parse(localStorage.getItem('medico-pyq-progress-v1')||'{}');if(x&&typeof x==='object'&&!Array.isArray(x))for(const [id,v] of Object.entries(x))if(v&&(v.choice===null||Number.isInteger(v.choice)&&v.choice>=0&&v.choice<4))pyqProgress[id]={choice:v.choice,hint:Number.isInteger(v.choice)&&v.hint===true,solved:Number.isInteger(v.choice)&&v.solved===true,bookmark:v.bookmark===true,note:typeof v.note==='string'?v.note.slice(0,2000):''};}catch{}
function savePyq(){try{localStorage.setItem('medico-pyq-progress-v1',JSON.stringify(pyqProgress));}catch{toast('Question progress could not be saved.');}}
async function loadPyqs(){if(pyqQuestions.length)return pyqQuestions;if(!pyqRequest)pyqRequest=fetch('pyq/questions.json').then(r=>{if(!r.ok)throw Error('Question bank could not load');return r.json();}).then(data=>{if(!Array.isArray(data)||data.length!==PYQ_CATALOG.count||!data.every(q=>typeof q.id==='string'&&typeof q.question==='string'&&Array.isArray(q.options)&&q.options.length===4&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<4))throw Error('Question data failed validation');pyqQuestions=data;return data;}).catch(e=>{pyqRequest=null;throw e;});return pyqRequest;}
function pyqLabel(id){return subj(id)?.name||(id==='dental'?'Dental':'Unclassified source questions');}
function filteredPyqs(){return pyqQuestions.filter(q=>(pyqSubject==='all'||q.subject===pyqSubject)&&(!pyqQuery||(q.question+' '+q.topic).toLowerCase().includes(pyqQuery.toLowerCase()))&&(pyqMode==='all'||pyqMode==='unanswered'&&!pyqProgress[q.id]?.solved||pyqMode==='mistakes'&&pyqProgress[q.id]?.solved&&pyqProgress[q.id].choice!==q.answer||pyqMode==='bookmarked'&&pyqProgress[q.id]?.bookmark||pyqMode==='explained'&&q.explanation.trim().length>=200));}
function pyqSourceCredit(){return '<p class="fine pyq-source-credit">Source: <a href="'+PYQ_CATALOG.source+'" target="_blank" rel="noopener">MedMCQA validation split</a>, Pal, Umapathi & Sankarasubbu (2022). <a href="'+PYQ_CATALOG.paper+'" target="_blank" rel="noopener">Dataset paper</a> · <a href="pyq/LICENSE-APACHE-2.0.txt">Apache 2.0 dataset license</a> · <a href="pyq/LICENSE-MIT.txt">Upstream MIT license</a>. Answers and explanations are dataset annotations, not an official NBEMS key. Exam years are not supplied; this is not every historic paper.</p>';}
async function pyqLibrary(){const token=++pyqRouteToken;main.innerHTML='<div class="page-head"><span class="eyebrow">QUESTION PRACTICE</span><h1>NEET PG PYQ practice.</h1><p>Try the question first, use a hint, then study the source answer and explanation.</p></div><div class="metric-line"><span>'+PYQ_CATALOG.count.toLocaleString()+' imported questions</span><span>'+PYQ_CATALOG.withExplanation.toLocaleString()+' source explanations</span><span>Entire available development split</span></div><div class="notice">These questions come from the split identified as NEET PG exam MCQs by the MedMCQA authors. Individual exam years and complete historical coverage are unverified. Some source explanations are short or missing; those gaps are shown explicitly. Of the 4,183 records, 2,843 are classified in medical subjects, 1,318 are Dental and 22 are unclassified. There are no Orthopedics-classified records in this split. These categories are retained and labeled separately.</div><section class="pyq-filters panel"><div><label for="pyq-subject">Subject</label><select id="pyq-subject"><option value="all">All records, including Dental</option>'+Object.keys(PYQ_CATALOG.subjects).sort((a,b)=>pyqLabel(a).localeCompare(pyqLabel(b))).map(id=>'<option value="'+id+'" '+(id===pyqSubject?'selected':'')+'>'+esc(pyqLabel(id))+' ('+PYQ_CATALOG.subjects[id]+')</option>').join('')+'</select></div><div><label for="pyq-mode">Practice set</label><select id="pyq-mode">'+[['all','All questions'],['unanswered','Not solved yet'],['mistakes','My incorrect answers'],['bookmarked','Bookmarked'],['explained','With substantial source explanation']].map(([id,label])=>'<option value="'+id+'" '+(id===pyqMode?'selected':'')+'>'+label+'</option>').join('')+'</select></div><div><label for="pyq-search">Search question or topic</label><input type="search" id="pyq-search" value="'+esc(pyqQuery)+'" placeholder="Search within the bank…"></div></section><p id="pyq-count" role="status">Loading questions…</p><div id="pyq-list" class="pyq-list"></div><div id="pyq-pager"></div>'+pyqSourceCredit();try{await loadPyqs();if(token===pyqRouteToken&&location.hash==='#pyq')renderPyqList();}catch{if(token===pyqRouteToken&&location.hash==='#pyq')$('#pyq-list').innerHTML='<div class="empty"><p>Question data could not load. Check the local server and retry.</p><button class="btn" data-action="pyq-retry">Retry loading</button></div>';}}
function renderPyqList(){const qs=filteredPyqs();const pages=Math.max(1,Math.ceil(qs.length/20));pyqPage=Math.max(0,Math.min(pyqPage,pages-1));const solved=pyqQuestions.filter(q=>pyqProgress[q.id]?.solved);const correct=solved.filter(q=>pyqProgress[q.id].choice===q.answer);$('#pyq-count').textContent=qs.length+' matching questions · '+solved.length+' solutions reviewed · '+correct.length+' correct reviewed answers';$('#pyq-list').innerHTML=qs.length?qs.slice(pyqPage*20,pyqPage*20+20).map(q=>{const s=pyqProgress[q.id];return '<article class="pyq-preview panel"><span class="eyebrow">'+esc(pyqLabel(q.subject))+' · '+(q.explanation.length>=200?'SOURCE EXPLANATION':q.explanation.trim()?'SHORT SOURCE EXPLANATION':'EXPLANATION MISSING')+'</span><h2><a href="#pyq/'+q.id+'">'+esc(q.question)+'</a></h2><p class="fine">'+esc(q.topic||'Topic not supplied')+' · '+(s?.solved?(s.choice===q.answer?'Answered correctly':'Revisit your answer'):'Try yourself first')+(s?.bookmark?' · Bookmarked':'')+'</p><a class="btn secondary" href="#pyq/'+q.id+'">Try this question →</a></article>';}).join(''):'<div class="empty"><h2>No questions match</h2><p>Change the subject, search text, or practice set.</p></div>';$('#pyq-pager').innerHTML='<div class="pager"><button class="btn secondary" data-action="pyq-prev-page" '+(pyqPage===0?'disabled':'')+'>Previous</button><span>Page '+(pyqPage+1)+' of '+pages+'</span><button class="btn secondary" data-action="pyq-next-page" '+(pyqPage===pages-1?'disabled':'')+'>Next</button></div>';}
function pyqHint(q){const exception=/\b(not|except|false|incorrect|least|unlikely)\b/i.test(q.question);return (q.topic?'Focus on '+q.topic+'. ':'Start with the core principle in '+pyqLabel(q.subject)+'. ')+(exception?'The stem asks for an exception or a negative statement. Evaluate each option against the usual rule instead of selecting a familiar true statement. ':'Identify exactly what the stem asks you to distinguish. State the relevant mechanism or definition before evaluating the four alternatives. ')+(SUBJECT_GUIDES[q.subject]?.task||'Compare the choices using a reviewed reference, keeping your reasoning separate from the source key.');}
function pyqExplanation(q){if(!q.explanation.trim())return '<p class="notice">This source record supplies an answer key but no explanation. A detailed rationale has not been fabricated. Use the subject readings below to verify the mechanism and write your own account.</p>';return '<div class="pyq-explanation">'+q.explanation.trim().split(/\n+/).map(p=>'<p>'+esc(p)+'</p>').join('')+'</div>'+(q.explanation.trim().length<200?'<p class="fine">The source rationale is brief. It is shown in full; it is not a detailed explanation of every distractor.</p>':'');}
async function pyqQuestion(id){const token=++pyqRouteToken;pyqSolutionOpen=false;main.innerHTML='<div class="panel"><p role="status">Loading question…</p></div>';try{await loadPyqs();if(token!==pyqRouteToken||location.hash!=='#pyq/'+id)return;const q=pyqQuestions.find(q=>q.id===id);if(!q)return notFound();renderPyqQuestion(q);}catch{if(token===pyqRouteToken)main.innerHTML='<div class="empty"><p>This question could not load.</p><a class="btn" href="#pyq">Return to the question bank</a></div>';}}
function renderPyqQuestion(q){const s=pyqProgress[q.id],hasAttempt=Number.isInteger(s?.choice);main.innerHTML='<article class="pyq-workspace"><a class="eyebrow" href="#pyq">QUESTION BANK / '+esc(pyqLabel(q.subject))+'</a><h1>'+esc(q.question)+'</h1><p class="fine">'+esc(q.topic||'Topic not supplied')+' · Exam year not verified · Source record '+esc(q.id)+'</p><div class="pyq-steps" aria-label="Practice stages"><span class="current">1 · Try yourself</span><span class="'+(s?.hint?'current':'')+'">2 · Hint</span><span class="'+(pyqSolutionOpen?'current':'')+'">3 · Solution</span></div><section class="panel pyq-attempt"><h2>1. Try yourself</h2><p>Choose an answer before reading any help. Combination-style choices are kept exactly as supplied; select the one option recorded by the source key.</p><form id="pyq-attempt-form" data-question="'+q.id+'"><fieldset><legend class="sr-only">Choose your answer</legend>'+q.options.map((o,i)=>'<label class="pyq-option"><input type="radio" name="pyq-answer" value="'+i+'" '+(s?.choice===i?'checked':'')+' '+(hasAttempt?'disabled':'')+' required><span><strong>'+String.fromCharCode(65+i)+'.</strong> '+esc(o)+'</span></label>').join('')+'</fieldset><button class="btn" type="submit" '+(hasAttempt?'disabled':'')+'>Save answer and continue</button></form><p role="status">'+(hasAttempt?'Your answer is recorded. Continue with the hint before revealing the solution.':'The answer remains hidden until the solution stage.')+'</p></section><section class="panel pyq-hint"><h2>2. Hint</h2>'+(s?.hint?'<p>'+esc(pyqHint(q))+'</p>':'<p>Use a reasoning cue without revealing the source answer.</p><button class="btn secondary" data-action="pyq-hint" data-id="'+q.id+'" '+(!hasAttempt?'disabled':'')+'>Show hint</button>')+'</section><section class="panel pyq-solution"><h2>3. Detailed solution</h2>'+(pyqSolutionOpen?'<p class="notice"><strong>'+(s.choice===q.answer?'Your answer matches the source key.':'Your answer differs from the source key.')+'</strong> You chose '+String.fromCharCode(65+s.choice)+'. The source key is '+String.fromCharCode(65+q.answer)+': '+esc(q.options[q.answer])+'.</p><h3>Source explanation</h3>'+pyqExplanation(q)+contextualWordHelp(q.question+' '+q.options.join(' ')+' '+q.explanation)+'<h3>Compare the alternatives</h3><table class="pyq-comparison"><thead><tr><th>Option</th><th>Source-key comparison</th></tr></thead><tbody>'+q.options.map((o,i)=>'<tr><td>'+String.fromCharCode(65+i)+'. '+esc(o)+'</td><td>'+(i===q.answer?'Recorded source answer':'Not the recorded source answer')+'</td></tr>').join('')+'</tbody></table><p>Explain why the source answer fits the stem and which assumption separates it from your strongest alternative. The comparison above identifies the key; it does not invent an option-specific medical explanation.</p><label for="pyq-reasoning">Your corrected explanation and remaining question</label><textarea id="pyq-reasoning" data-pyq-note="'+q.id+'" maxlength="2000" rows="5">'+esc(s.note||'')+'</textarea><p class="fine">Your reflection is saved on this device as you type.</p><h3>Continue studying the subject</h3>'+(subj(q.subject)?'<a class="btn secondary" href="#subject/'+q.subject+'">Open '+esc(pyqLabel(q.subject))+' study material</a>':'<a href="#study" class="btn secondary">Open the textbook library</a>'):'<p>After trying the question and reading the hint, reveal the source answer and its available explanation.</p><button class="btn" data-action="pyq-solution" data-id="'+q.id+'" '+(!s?.hint?'disabled':'')+'>Reveal solution</button>')+'</section><div class="buttons"><button class="btn secondary" data-action="pyq-bookmark" data-id="'+q.id+'" '+'>'+(s?.bookmark?'Remove bookmark':'Bookmark for review')+'</button><button class="btn secondary" data-action="pyq-reset" data-id="'+q.id+'" '+(!hasAttempt?'disabled':'')+'>Try again</button><button class="btn" data-action="pyq-next" data-id="'+q.id+'">Next question →</button></div>'+pyqSourceCredit()+'</article>';}
function recordPyqAnswer(id,choice){const q=pyqQuestions.find(q=>q.id===id);if(!q||!Number.isInteger(choice)||choice<0||choice>3||Number.isInteger(pyqProgress[id]?.choice))return false;const old=pyqProgress[id];pyqProgress[id]={choice,hint:false,solved:false,bookmark:old?.bookmark||false,note:old?.note||''};savePyq();renderPyqQuestion(q);return true;}
function pyqSubjectLink(id){const count=PYQ_CATALOG.subjects[id]||0;return count?'<section class="panel workbook-context"><h2>Practise '+count+' source PYQs in '+esc(pyqLabel(id))+'</h2><p>Try each question, use its reasoning hint, then review the dataset answer and available explanation. Save the corrected reasoning and return to mistakes.</p><button class="btn" data-action="pyq-subject" data-id="'+id+'">Open subject PYQs</button></section>':'';}
document.addEventListener('submit',e=>{if(e.target.id==='pyq-attempt-form'){e.preventDefault();const choice=e.target.querySelector('input[name="pyq-answer"]:checked');if(choice)recordPyqAnswer(e.target.dataset.question,Number(choice.value));}});
document.addEventListener('change',e=>{if(e.target.id==='pyq-subject')pyqSubject=e.target.value;else if(e.target.id==='pyq-mode')pyqMode=e.target.value;else return;pyqPage=0;renderPyqList();});
document.addEventListener('input',e=>{if(e.target.id==='pyq-search'){pyqQuery=e.target.value.slice(0,200);pyqPage=0;renderPyqList();}const id=e.target.dataset?.pyqNote;if(id&&pyqProgress[id]){pyqProgress[id].note=e.target.value.slice(0,2000);savePyq();}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id,q=pyqQuestions.find(q=>q.id===id),s=pyqProgress[id];if(action==='pyq-retry')pyqLibrary();if(action==='pyq-prev-page'||action==='pyq-next-page'){pyqPage+=action==='pyq-next-page'?1:-1;renderPyqList();}if(action==='pyq-subject'){pyqSubject=id;pyqPage=0;pyqQuery='';pyqMode='all';navigate('#pyq');}if(!q)return;if(action==='pyq-hint'&&Number.isInteger(s?.choice)){s.hint=true;savePyq();renderPyqQuestion(q);}if(action==='pyq-solution'&&s?.hint&&Number.isInteger(s.choice)){s.solved=true;pyqSolutionOpen=true;savePyq();renderPyqQuestion(q);}if(action==='pyq-bookmark'){const item=s||{choice:null,hint:false,solved:false,bookmark:false,note:''};item.bookmark=!item.bookmark;pyqProgress[id]=item;savePyq();renderPyqQuestion(q);}if(action==='pyq-reset'&&s){pyqProgress[id]={choice:null,hint:false,solved:false,bookmark:s.bookmark,note:s.note};pyqSolutionOpen=false;savePyq();renderPyqQuestion(q);}if(action==='pyq-next'){const qs=filteredPyqs();const at=qs.findIndex(x=>x.id===id);const next=qs.length?qs[(at+1)%qs.length]:pyqQuestions[(pyqQuestions.indexOf(q)+1)%pyqQuestions.length];navigate('#pyq/'+next.id);}});
